using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private string? method, path, contentType, body;

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        var prefix = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(prefix);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(prefix) };
    }

    private static int FreePort()
    {
        var l = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        l.Start();
        var port = ((IPEndPoint)l.LocalEndpoint).Port;
        l.Stop();
        return port;
    }

    private Task Respond(int status, string responseBody) => Task.Run(async () =>
    {
        var ctx = await listener.GetContextAsync();
        method = ctx.Request.HttpMethod;
        path = ctx.Request.Url!.AbsolutePath;
        contentType = ctx.Request.ContentType;
        using (var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8)) body = await reader.ReadToEndAsync();
        var bytes = Encoding.UTF8.GetBytes(responseBody);
        ctx.Response.StatusCode = status;
        ctx.Response.ContentType = "application/json";
        await ctx.Response.OutputStream.WriteAsync(bytes);
        ctx.Response.Close();
    });

    private async Task<AuthorizationOutcome> Authorize(int status, string responseBody)
    {
        var served = Respond(status, responseBody);
        var outcome = await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);
        await served;
        return outcome;
    }

    [Fact]
    public async Task Sends_a_json_POST_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        await Authorize(200, """{"status":"approved"}""");

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_approved() =>
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(200, """{"status":"approved"}"""));

    [Fact]
    public async Task A_declined_answer_is_declined() =>
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(200, """{"status":"declined"}"""));

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored() =>
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(200, """{"id":"a1","status":"approved","risk":{"score":3}}"""));

    [Fact]
    public async Task A_402_refusal_is_declined_not_an_error() =>
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(402, """{"error":"card_refused"}"""));

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"result":"approved"}""")]
    [InlineData("{}")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_explicit_approval_is_never_approved(string answer) =>
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(200, answer));

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_surface_as_errors_rather_than_a_decision(int status)
    {
        var ex = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(status, """{"status":"approved"}"""));
        Assert.Equal((HttpStatusCode)status, ex.StatusCode);
    }

    [Fact]
    public async Task An_unparseable_answer_surfaces_as_an_error() =>
        await Assert.ThrowsAsync<JsonException>(() => Authorize(200, "<html>oops</html>"));

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
